/* Merchant-facing UI. Local synthetic adapter only; no provider requests or credentials. */
(()=>{
'use strict';
const $=selector=>document.querySelector(selector);
const $$=(selector,scope=document)=>[...scope.querySelectorAll(selector)];
const escape=value=>String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const formatDate=value=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Kolkata'}).format(new Date(value+'T12:00:00+05:30'));
const icons={
 home:'<path d="m3 10 9-7 9 7v10H3z"/><path d="M9 20v-7h6v7"/>',
 receipt:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2z"/><path d="M8 7h8M8 11h8M8 15h4"/>',
 users:'<circle cx="9" cy="8" r="3"/><path d="M3 20v-3a6 6 0 0 1 12 0v3M17 5a3 3 0 0 1 0 6M18 14a5 5 0 0 1 3 6"/>',
 grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
 layers:'<path d="m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5"/>',
 link:'<path d="m10 14 4-4M8 16l-1 1a4 4 0 0 1-6-6l5-5a4 4 0 0 1 6 0M16 8l1-1a4 4 0 0 1 6 6l-5 5a4 4 0 0 1-6 0"/>',
 help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 4 2c-1 .5-1.5 1-1.5 2M12 17h.01"/>',
 sliders:'<path d="M3 6h8m4 0h6M3 12h3m4 0h11M3 18h11m4 0h3"/><circle cx="13" cy="6" r="2"/><circle cx="8" cy="12" r="2"/><circle cx="16" cy="18" r="2"/>',
 pause:'<path d="M8 5v14M16 5v14"/>',play:'<path d="m8 4 13 8-13 8z"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>',down:'<path d="m6 9 6 6 6-6"/>',close:'<path d="m6 6 12 12M18 6 6 18"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
 check:'<path d="m5 12 4 4L19 6"/>',circlecheck:'<circle cx="12" cy="12" r="9"/><path d="m7 12 3 3 7-7"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',
 message:'<path d="M3 4h18v13H8l-5 4z"/><path d="M7 8h10M7 12h7"/>',phone:'<path d="M5 3h4l2 5-3 2a14 14 0 0 0 6 6l2-3 5 2v4a2 2 0 0 1-2 2C10 21 3 14 3 5a2 2 0 0 1 2-2z"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',
 alert:'<path d="m12 3 10 18H2zM12 9v5M12 17h.01"/>',shield:'<path d="m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z"/><path d="m8 12 3 3 5-6"/>',
 box:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7 5l9 5"/>',plus:'<path d="M12 5v14M5 12h14"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M19 11a7 7 0 0 0-12-6L4 8M5 13a7 7 0 0 0 12 6l3-3"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',mic:'<rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/>',
 external:'<path d="M14 3h7v7M21 3 10 14M10 3H3v18h18v-7"/>',ban:'<circle cx="12" cy="12" r="9"/><path d="m6 6 12 12"/>'
};
function icon(name){return '<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">'+(icons[name]||icons.info)+'</svg>';}
function applyIcons(root=document){$$('[data-icon]',root).forEach(element=>{if(!element.querySelector('svg'))element.insertAdjacentHTML('afterbegin',icon(element.dataset.icon));});$$('[data-static-icon]',root).forEach(element=>element.innerHTML=icon(element.dataset.staticIcon));}
const storageKey='repeat-purchase-merchant-preview-v2';
function initialState(scenario='operating'){
 return {scenario,installed:scenario!=='setup',paused:false,mode:'review',policy:{version:3,start:'10:00',end:'18:00',cap:2,budget:500,offers:false},planApproved:scenario==='operating',planNeedsReview:false,planVersion:1,selected:['ananya','rahul','meera'],supportOwner:'',checkoutApproved:false,owner:'agent',messages:[],reminderDate:'2026-10-16',planDate:'2026-10-12',audienceExcluded:[],events:[],orderConfirmed:scenario==='operating',assigned:scenario==='operating'?['ananya','rahul','meera']:[],disconnected:scenario==='disconnected'};
}
let state;
try{const saved=JSON.parse(localStorage.getItem(storageKey));state=saved?.schema===2?{...initialState(saved.data.scenario),...saved.data}:initialState();}catch{state=initialState();}
const people={ananya:{name:'Ananya Sharma',id:'C001',initials:'AS',channel:'WhatsApp',product:'Laundry liquid · 1 L',delivered:'12 Sep 2026'},rahul:{name:'Rahul Mehta',id:'C002',initials:'RM',channel:'Voice → WhatsApp',product:'Laundry liquid · 1 L',delivered:'8 Sep 2026'},meera:{name:'Meera Shah',id:'C003',initials:'MS',channel:'Outside agent link',product:'Laundry liquid · 1 L',delivered:'10 Sep 2026'},support:{name:'Priya Nair',id:'C006',initials:'PN',channel:'WhatsApp',product:'Laundry liquid · 1 L',delivered:'Not delivered'},optout:{name:'Customer C005',id:'C005',initials:'C5',channel:'WhatsApp',product:'Laundry liquid · 1 L',delivered:'9 Sep 2026'}};
let lastFocus=null,toastTimer,activityFilter='all',activityQuery='';
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({schema:2,data:state}));}catch{} }
function event(type,description){state.events.unshift({type,description,time:'12 Oct 2026 · test event'});persist();}
function notify(text){clearTimeout(toastTimer);$('#toast').textContent=text;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4200);}
function badge(text,tone=''){return '<span class="pill '+tone+'">'+escape(text)+'</span>';}
function customer(key){const person=people[key];return '<div class="customer-cell"><span class="avatar">'+person.initials+'</span><div><strong>'+person.name+'</strong><small>'+person.id+'</small></div></div>';}
function button(text,action,primary=false,iconName='',extra=''){return '<button class="button '+(primary?'primary':'secondary')+'" data-action="'+action+'" '+extra+'>'+(iconName?icon(iconName):'')+text+'</button>';}
function textButton(text,action,iconName=''){return '<button class="text-button" data-action="'+action+'">'+text+(iconName?icon(iconName):'')+'</button>';}
function panel(title,body,extra=''){return '<section class="panel"><div class="panel-heading"><h2>'+title+'</h2>'+extra+'</div>'+body+'</section>';}
function metrics(){const hasOrder=state.orderConfirmed;return '<div class="metric-strip"><div class="metric"><div class="metric-label">Customers assigned</div><div class="metric-value">'+(state.assigned.length)+'</div><div class="metric-caption">'+(state.assigned.length?'Plan RP-014 · all versions':'No approved audience')+'</div></div><div class="metric"><div class="metric-label">Repeat orders</div><div class="metric-value">'+(hasOrder?'1':'0')+'</div><div class="metric-caption">'+(hasOrder?'₹499 net revenue':'Verified purchases only')+'</div></div><div class="metric"><div class="metric-label">Reminders scheduled</div><div class="metric-value">'+(state.planApproved&&state.scenario==='operating'?'1':'0')+'</div><div class="metric-caption">'+(state.planApproved&&state.scenario==='operating'?'Next: 16 Oct, 10:00':'Customer-confirmed dates')+'</div></div><div class="metric"><div class="metric-label">Net contribution</div><div class="metric-value word">Not available</div><div class="metric-caption">Cost data incomplete</div></div></div>';}
function mandate(){return panel('Operating limits','<div class="operating-list"><div class="operating-item"><span>Execution</span><strong>'+ (state.mode==='review'?'Review-first':'Within approved limits')+'</strong></div><div class="operating-item"><span>Contact hours</span><strong>'+state.policy.start+'–'+state.policy.end+' IST</strong></div><div class="operating-item"><span>Contact cap</span><strong>'+state.policy.cap+' per customer</strong></div><div class="operating-item"><span>Spend limit</span><strong>₹'+state.policy.budget+'</strong></div><div class="operating-item"><span>Offers</span><strong>'+(state.policy.offers?'Approved offers only':'Off')+'</strong></div></div><div class="panel-bottom">'+textButton('Manage limits','settings','chevron')+'</div>','<span class="small muted">Policy v'+state.policy.version+'</span>');}
function decisions(){
 if(!state.installed)return panel('Complete setup','<div class="review-item"><h3>Set up your repeat purchase agent</h3><p>Choose products, connect your data and set contact limits.</p><div class="review-actions">'+button('Continue setup','install',true)+'</div></div>');
 if(state.disconnected)return panel('Needs attention','<div class="review-item"><div class="review-label">'+icon('link')+'Commerce connection</div><h3>Order data is unavailable</h3><p>Reconnect Shopify before scheduling outreach or preparing a checkout.</p><div class="review-actions">'+button('Review connection','connections',true)+'</div></div>');
 if(state.planNeedsReview)return panel('Needs approval','<div class="review-item"><div class="review-label">'+icon('shield')+'Policy changed</div><h3>Review your active plan</h3><p>Your contact limits have changed. Review the affected customers before outreach resumes.</p><div class="review-actions">'+button('Review plan','plan',true)+'</div></div>','<span class="count">1 plan</span>');
 if(!state.planApproved)return panel('Needs approval','<div class="review-item"><div class="review-label">'+icon('users')+'Audience review</div><h3>Review your first reorder plan</h3><p>3 customers are eligible for the laundry liquid reorder journey.</p><div class="customer-chip">'+badge('Same product')+badge('WhatsApp & voice')+'</div><div class="review-actions">'+button('Review plan','plan',true)+textButton('View exclusions','exclusions')+'</div></div>','<span class="count">1 plan</span>');
 if(state.scenario!=='operating')return panel('Approvals','<div class="decision-empty">'+icon('circlecheck')+'<div><strong>No actions waiting for approval</strong><p>Your plan is scheduled. Customer replies and proposed actions will appear here.</p></div></div>');
 let html='';
 if(!state.supportOwner)html+='<article class="review-item"><div class="review-label">'+icon('alert')+'Customer issue</div><h3>A delivery issue needs an owner</h3><p>Priya hasn’t received her previous order. Reorder outreach is blocked.</p><div class="customer-chip"><span class="avatar">PN</span>Priya Nair<span class="mini-separator">·</span><span class="muted">Today, 10:22</span></div><div class="review-actions">'+button('Review issue','journey:support',true)+textButton('Assign to me','assign-support')+'</div></article>';
 if(!state.checkoutApproved)html+='<article class="review-item"><div class="review-label">'+icon('message')+'Action approval</div><h3>Send Rahul his checkout link</h3><p>He confirmed the same bottle and asked to complete his order on WhatsApp.</p><div class="customer-chip"><span class="avatar">RM</span>Rahul Mehta<span class="mini-separator">·</span><span class="muted">₹499 · 1 item</span></div><div class="review-actions">'+button('Review message','journey:rahul',!html)+textButton('View plan','plan')+'</div></article>';
 if(!html)html='<div class="decision-empty">'+icon('circlecheck')+'<div><strong>You’re up to date</strong><p>No actions need your approval. The next reminder is scheduled for 16 Oct.</p></div></div>';
 return panel('Needs your attention',html,'<span class="count">'+(Number(!state.supportOwner)+Number(!state.checkoutApproved))+' items</span>');
}
function journeyRows(keys=['ananya','rahul','meera']){
 return keys.map(key=>{let title,detail,tone,status;
 if(key==='ananya'){title='Reminder scheduled';detail='16 Oct, 10:00 · WhatsApp';tone='teal';status='Scheduled';}
 if(key==='rahul'){title=state.checkoutApproved?'Checkout link sent':'Checkout ready for review';detail=state.checkoutApproved?'Awaiting payment':'Voice request · WhatsApp handoff';tone=state.checkoutApproved?'blue':'amber';status=state.checkoutApproved?'Awaiting payment':'Needs approval';}
 if(key==='meera'){title=state.scenario==='operating'?'Order confirmed':'Waiting for reply';detail=state.scenario==='operating'?'Order LE-1048 · ₹499':'No purchase recorded';tone=state.scenario==='operating'?'teal':'';status=state.scenario==='operating'?'Purchased':'Awaiting reply';}
 if(key==='support'){title='Delivery issue';detail=state.supportOwner?'Assigned to you':'Owner not assigned';tone='red';status='Outreach blocked';}
 if(key==='optout'){title='Marketing opt-out';detail='Queued messages and calls cancelled';tone='';status='Suppressed';}
 if(state.scenario!=='operating'&&['ananya','rahul','meera'].includes(key)){title='Outreach scheduled';detail='Starts '+formatDate(state.planDate)+' · '+(key==='rahul'?'Voice':'WhatsApp');tone='blue';status='Scheduled';}return '<tr><td>'+customer(key)+'</td><td><span class="table-primary">'+title+'</span><span class="table-secondary">'+detail+'</span></td><td>'+escape(people[key].channel)+'</td><td class="table-status">'+badge(status,tone)+'</td><td>'+ '<button class="icon-button row-open" data-action="journey:'+key+'" aria-label="Open '+people[key].name+'">'+icon('chevron')+'</button></td></tr>';}).join('');
}
function journeyTable(keys){return '<div class="table-scroll" role="region" aria-label="Customer journeys" tabindex="0"><table class="customer-table journey-table"><thead><tr><th>Customer</th><th>Latest activity</th><th>Channel</th><th>Status</th><th><span class="sr-only">Details</span></th></tr></thead><tbody>'+journeyRows(keys)+'</tbody></table></div>';}
function dashboard(){return '<div class="page-toolbar"><div><h2>Overview</h2><p class="description">Your current plan, approvals and customer activity.</p></div><div class="period">'+icon('calendar')+'12–16 Oct 2026</div></div>'+metrics()+'<div class="columns"><div>'+decisions()+'<div class="section-space dashboard-table">'+panel('Customer activity',state.planApproved?journeyTable(state.selected):'<div class="empty-view"><h3>No active customer journeys</h3><p>Approve a plan to schedule customer contact.</p>'+button('Review plan','plan',true)+'</div>',textButton('View all','activity','arrow'))+'</div></div><div>'+mandate()+'<div class="section-space">'+panel('Next scheduled','<div class="timeline-note">'+icon('clock')+'<div><strong>'+(state.planApproved&&state.scenario==='operating'?'Ananya’s reorder reminder':state.planApproved?'Plan outreach begins':'No outreach scheduled')+'</strong><p>'+(state.planApproved&&state.scenario==='operating'?'16 Oct, 10:00 IST · WhatsApp':state.planApproved?formatDate(state.planDate)+' · within contact hours':'Approve a plan to schedule customer contact.')+'</p></div></div>','')+'</div></div></div><div class="connection-summary"><span>'+icon('link')+(state.disconnected?'Shopify requires attention':'Commerce, payments, WhatsApp, voice and support use test data')+'</span>'+textButton('View connections','connections')+'</div>';}
function activity(){let keys=state.planApproved?['support','rahul','ananya','meera','optout']:['optout'];if(activityFilter==='approval')keys=keys.filter(k=>k==='rahul'&&!state.checkoutApproved);if(activityFilter==='scheduled')keys=keys.filter(k=>k==='ananya');if(activityFilter==='blocked')keys=keys.filter(k=>['support','optout'].includes(k));if(activityQuery)keys=keys.filter(k=>(people[k].name+' '+people[k].id).toLowerCase().includes(activityQuery.toLowerCase()));return '<div class="page-toolbar"><div><h2>Customer activity</h2><p class="description">Messages, calls and order updates in one place.</p></div>'+button('View outcomes','outcomes',false,'receipt')+'</div><div class="filters"><div class="search">'+icon('search')+'<input id="activity-search" aria-label="Search customers" placeholder="Search by name or customer ID" value="'+escape(activityQuery)+'"></div><select id="activity-filter" aria-label="Filter activity"><option value="all">All activity</option><option value="approval">Needs approval</option><option value="scheduled">Scheduled</option><option value="blocked">Blocked or suppressed</option></select></div>'+panel('Latest activity',keys.length?journeyTable(keys):'<div class="empty-view"><h3>No matching activity</h3><p>Try another name or remove the status filter.</p>'+textButton('Clear filters','clear-filters')+'</div>','<span class="count">'+keys.length+' customers</span>');}
function customerPreferences(){return panel('Customer preferences',state.scenario==='operating'?'<div class="learning-note">'+icon('clock')+'<div><strong>Ananya’s reminder date is saved</strong><p>16 Oct, 10:00 IST · WhatsApp. This date takes priority over an estimated repeat window.</p></div></div><div class="learning-note">'+icon('phone')+'<div><strong>Rahul requested a WhatsApp checkout</strong><p>This request applies to his current order. His preferred contact channel has not changed.</p></div></div><div class="outcome-note">More purchase history is needed before recommending a change to your operating policy.</div>':'<div class="review-item"><h3>No confirmed preferences yet</h3><p>Customer-requested reminder dates and channel preferences will appear here.</p></div>');}
function outcomes(){const hasOrder=state.orderConfirmed;return '<div class="page-toolbar"><div><h2>Outcomes</h2><p class="description">Orders from your assigned customers, including purchases outside agent links.</p></div>'+textButton('Back to activity','activity','back')+'</div>'+metrics()+panel('Orders',hasOrder?'<div class="table-scroll"><table class="customer-table"><thead><tr><th>Order</th><th>Customer</th><th>Order source</th><th class="amount">Net revenue</th><th>Status</th></tr></thead><tbody><tr><td><button class="text-button" data-action="calculation">LE-1048</button><span class="table-secondary">12 Oct, 11:12</span></td><td>'+customer('meera')+'</td><td>Outside agent link</td><td class="amount">₹499</td><td>'+badge('Confirmed','teal')+'</td></tr></tbody></table></div>':'<div class="empty-view"><h3>No confirmed orders yet</h3><p>Orders appear after payment and commerce records are matched.</p></div>','<span class="count">12–16 Oct 2026</span>')+'<div class="section-space columns"><div>'+panel('Contribution','<div class="review-item"><h3>Add product and delivery costs</h3><p>Net revenue is available. Contribution will be shown when all required costs can be verified.</p><div class="review-actions">'+textButton('View calculation','calculation','chevron')+'</div></div><div class="outcome-note">Orders are still within the return window. Figures may change after refunds.</div>')+'</div><div>'+panel('Incremental impact','<div class="review-item"><h3>Not measured</h3><p>A comparable customer group is required to measure incremental contribution.</p></div>')+'</div></div><div class="section-space">'+customerPreferences()+'</div>';}
function settings(){return '<div class="page-toolbar"><div><h2>Operating policy</h2><p class="description">Choose what the agent can do and when it needs your approval.</p></div><span class="small muted">Policy v'+state.policy.version+'</span></div><div class="settings-layout"><form class="panel" id="policy-form"><div class="settings-body"><section class="form-section"><h3>Products</h3><p>Reorders are limited to the customer’s previously purchased variant.</p><label class="checkbox-field"><input type="checkbox" checked disabled><span><strong>Laundry liquid · 1 L</strong><br><span class="muted">SKU LL-1L · same variant only</span></span></label></section><section class="form-section"><h3>Contact schedule</h3><p>Contact limits apply across WhatsApp and voice.</p><div class="field-grid"><div class="field"><label class="input-label" for="contact-start">Start time</label><input id="contact-start" name="start" type="time" value="'+state.policy.start+'" required></div><div class="field"><label class="input-label" for="contact-end">End time</label><input id="contact-end" name="end" type="time" value="'+state.policy.end+'" required></div></div><p class="field-help">Timezone: India Standard Time (IST)</p><div class="field-grid"><div class="field"><label class="input-label" for="contact-cap">Contacts per customer</label><input id="contact-cap" name="cap" type="number" min="1" step="1" value="'+state.policy.cap+'" required></div><div class="field"><label class="input-label" for="spend-limit">Contact spend limit (₹)</label><input id="spend-limit" name="budget" type="number" min="1" step="1" value="'+state.policy.budget+'" required></div></div></section><section class="form-section"><h3>Approval mode</h3><div class="mode-options"><label class="mode-option"><input type="radio" name="mode" value="review" '+(state.mode==='review'?'checked':'')+'><div><strong>Review-first</strong><span>Approve outgoing messages, calls and checkout actions before they run.</span></div></label><label class="mode-option"><input type="radio" name="mode" value="bounded" '+(state.mode==='bounded'?'checked':'')+'><div><strong>Within approved limits</strong><span>Allow routine actions within an approved plan. Exceptions still require review.</span></div></label></div></section><section class="form-section"><h3>Offers</h3><p>Only existing, eligible offers can be used for a price concern or coupon enquiry.</p><div class="pending-approval-note">Offers are off. No approved offers are available in this workspace.</div></section><p id="policy-error" class="field-error" role="alert"></p></div><div class="form-footer">'+button('Review changes','save-policy',true)+'</div></form><aside>'+panel('What changes affect','<div class="review-item"><p>Changes to channels, timing or limits require a fresh review of the affected plan.</p><div class="review-actions">'+textButton('View active plan','plan','chevron')+'</div></div>')+'<div class="section-space">'+panel('Connections','<div class="review-item"><p>Review access, data availability and service status.</p><div class="review-actions">'+textButton('Manage connections','connections','chevron')+'</div></div>')+'</div></aside></div>';}
const providers=[['Shopify','S','shopify','Orders, products, stock and checkout.'],['Razorpay','R','razorpay','Payment status and order reconciliation.'],['WhatsApp','W','whatsapp','Customer replies and permitted messages.'],['Browser voice','V','voice','Voice conversations and checkout handoffs.'],['Support & delivery','D','','Delivered orders and unresolved customer issues.']];
function connections(){return '<div class="page-toolbar"><div><h2>Connections</h2><p class="description">Data access and services used by your agent.</p></div>'+textButton('Back to dashboard','dashboard','back')+'</div><div class="notice warning">'+icon('info')+'<div><strong>This workspace uses test data</strong><p>Live accounts are not connected. Test actions do not contact customers.</p></div></div><div class="connection-grid">'+providers.map((p,i)=>'<article class="connection-card"><div class="provider-head"><span class="provider-logo '+p[2]+'">'+p[1]+'</span><h3>'+p[0]+'</h3>'+badge(state.disconnected&&i===0?'Disconnected':'Simulated',state.disconnected&&i===0?'red':'')+'</div><p>'+p[3]+'</p>'+textButton('Review access','provider:'+i,'chevron')+'</article>').join('')+'</div>';}
function studio(){return '<div class="page-toolbar"><div><h2>Explore agents</h2><p class="description">Specialists for your customer and payment operations.</p></div></div><div class="catalog"><article class="catalog-card"><div class="agent-symbol" aria-hidden="true"><span></span><span></span></div><h2>Repeat Purchase Agent</h2><p>Find customers due for a reorder. Adapt to their replies, schedule reminders and prepare same-product checkout.</p><div class="catalog-tags">'+badge('WhatsApp & voice')+badge('Merchant approvals')+'</div>'+button(state.installed?'Open agent':'Install agent',state.installed?'dashboard':'install',true)+'</article></div>';}
function plan(){const renewal=state.planNeedsReview;const approved=state.planApproved&&!renewal;const keys=approved?state.selected:renewal?['ananya','rahul']:['ananya','rahul','meera'];const selectedCount=keys.filter(key=>!state.audienceExcluded.includes(key)).length;return '<div class="page-toolbar"><div><h2>'+(approved?'Plan RP-014':'Review reorder plan')+'</h2><p class="description">Laundry liquid · 1 L · '+(approved?'Approved plan':'Audience and contact limits')+'</p></div>'+textButton('Back to dashboard','dashboard','back')+'</div><div class="plan-layout"><div class="panel"><div class="plan-header"><div><h3>'+keys.length+' eligible customers</h3><p>'+(approved?'Approved under policy v'+state.policy.version:'Only selected customers will be included.')+'</p></div>'+badge(approved?'Approved':'Needs approval',approved?'teal':'amber')+'</div>'+keys.map(key=>'<div class="plan-person"><div class="plan-person-top"><div class="audience-check">'+(!approved?'<input type="checkbox" aria-label="Include '+people[key].name+'" data-person="'+key+'" '+(!state.audienceExcluded.includes(key)?'checked':'')+'>':'')+customer(key)+'</div>'+textButton('Details','journey:'+key)+'</div><div class="plan-details">'+(key==='ananya'&&state.planApproved?'Customer-confirmed reminder: 16 Oct, 10:00 IST':key==='rahul'?'Repeat window: 12–16 Oct · product-level estimate':'Repeat window: 12–15 Oct · delivered purchase history')+'</div>'+(key==='ananya'&&!state.planApproved?'<div class="repeat-window" role="img" aria-label="Delivered 12 September; repeat window 11 to 14 October; today 12 October"><div class="window-bar"><span class="window-range"></span><span class="window-today"></span></div><div class="window-labels"><span>12 Sep · delivered</span><span>12 Oct · today</span></div><p class="window-basis">11–14 Oct · based on two previous purchase intervals</p></div>':'')+'</div>').join('')+'<div class="panel-bottom">'+textButton(renewal?'Meera excluded: recent purchase':'View excluded customers','exclusions')+'</div></div><aside class="panel"><div class="panel-heading"><h2>Plan limits</h2><span class="small muted">Policy v'+state.policy.version+'</span></div><div class="plan-settings">'+(!approved?'<div class="field"><label class="input-label" for="plan-date">Start date</label><input id="plan-date" type="date" value="'+state.planDate+'" min="2026-10-12" required><p class="field-help">Customer-confirmed reminder dates are preserved.</p></div>':'')+'<dl class="definition-list"><div><dt>Channels</dt><dd>WhatsApp & voice</dd></div><div><dt>Contact hours</dt><dd>'+state.policy.start+'–'+state.policy.end+' IST</dd></div><div><dt>Total contacts</dt><dd>'+state.policy.cap+' per customer</dd></div><div><dt>Spend limit</dt><dd>₹'+state.policy.budget+'</dd></div><div><dt>Offers</dt><dd>Off</dd></div><div><dt>Execution</dt><dd>'+(state.mode==='review'?'Review-first':'Within limits')+'</dd></div></dl><p class="field-help" style="margin-top:16px">Stock, permissions and new orders are checked again before each action.</p><p id="plan-error" class="field-error" role="alert"></p></div>'+(!approved?'<div class="form-footer">'+button('Reject plan','reject-plan')+button('Approve '+selectedCount+' '+(selectedCount===1?'customer':'customers'),'approve-plan',true,'',state.paused||state.disconnected||selectedCount===0?'disabled':'')+'</div>':'')+'</aside></div>';}
function route(){return location.hash.replace('#','')||'dashboard';}
function render(){
 const current=route();
 const globalView=['studio','connections','payments','transactions','customers'].includes(current);
 document.querySelector('.agent-heading h1').textContent=globalView?'Agent Studio':'Repeat Purchase Agent';
 document.querySelector('.agent-identity p').textContent=globalView?'Specialists for your merchant operations.':'Customer reorders, managed within your limits.';
 document.querySelector('.agent-controls').hidden=globalView;
 document.querySelector('.agent-tabs').hidden=globalView;
 const views={dashboard,activity,settings,connections,studio,plan,outcomes};
 if(['payments','transactions','customers'].includes(current)){ $('#page-content').innerHTML=panel(current==='payments'?'Payments workspace':current==='transactions'?'Transactions':'Customers','<div class="empty-view"><div class="empty-icon">'+icon(current==='customers'?'users':'receipt')+'</div><h3>'+(current==='payments'?'Manage your repeat purchase agent':'No live '+current+' connected')+'</h3><p>'+(current==='payments'?'Open your agent to review customer activity and approvals.':'Connect your merchant account to view this data.')+'</p>'+button('Open Repeat Purchase Agent','dashboard',true)+'</div>');}
 else $('#page-content').innerHTML=(views[current]||dashboard)();
 $$('.agent-tabs a').forEach(a=>{const target=a.getAttribute('href').slice(1);const selected=target===current||target==='dashboard'&&['plan','outcomes'].includes(current);if(selected)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});
 $$('.primary-nav a').forEach(a=>a.classList.toggle('selected',a.getAttribute('href')==='#'+(['connections','studio','payments','transactions','customers'].includes(current)?current:'dashboard')));
 $('#agent-status').innerHTML='<span class="status-dot"></span>'+(state.paused?'Paused':state.disconnected?'Needs attention':!state.installed?'Setup required':!state.planApproved?'Ready':'Active');$('#agent-status').className='status '+(state.paused||state.disconnected?'paused':'');
 $('#pause-button').innerHTML=icon(state.paused?'play':'pause')+(state.paused?'Resume agent':'Pause agent');$('#pause-button').disabled=!state.installed;
 $('#pause-notice').hidden=!state.paused;$('#activity-count').textContent=state.planApproved&&!state.checkoutApproved?'1':'0';$('#activity-count').hidden=!state.planApproved||state.checkoutApproved;
 if(current==='activity')$('#activity-filter').value=activityFilter;
 applyIcons();persist();
}
function go(view){if(route()===view)render();else location.hash=view;}
function openDrawer(title,eyebrow,content,footer=''){
 lastFocus=document.activeElement;if($('#modal').open)$('#modal').close();if($('#drawer').open)$('#drawer').close();$('#drawer-title').textContent=title;$('#drawer-eyebrow').textContent=eyebrow;$('#drawer-content').innerHTML=content;$('#drawer-footer').innerHTML=footer;$('#drawer-footer').hidden=!footer;applyIcons($('#drawer'));$('#drawer').showModal();$('#drawer-close').focus();
}
function openModal(title,content,footer='',wide=false){lastFocus=document.activeElement;if($('#drawer').open)$('#drawer').close();if($('#modal').open)$('#modal').close();$('#modal-title').textContent=title;$('#modal-content').innerHTML=content;$('#modal-footer').innerHTML=footer;$('#modal').classList.toggle('installation-dialog',wide);applyIcons($('#modal'));$('#modal').showModal();$('#modal-close').focus();}
function closeDialogs(){if($('#drawer').open)$('#drawer').close();if($('#modal').open)$('#modal').close();}
function fact(label,value,note=''){return '<div><span class="fact-label">'+label+'</span><span class="fact-value">'+value+'</span>'+(note?'<p class="fact-note">'+note+'</p>':'')+'</div>';}
function checks(items){return '<ul class="check-list">'+items.map(text=>'<li>'+icon('check')+'<span>'+text+'</span></li>').join('')+'</ul>';}
function chat(channel,messages){return '<div class="conversation"><div class="message-meta">'+icon(channel.includes('Voice')?'phone':'message')+channel+' · 12 Oct</div>'+messages.map(([sender,text,time])=>'<div class="bubble '+(sender==='agent'?'agent':'')+'">'+escape(text)+'<span class="message-time">'+time+'</span></div>').join('')+'</div>';}
function detail(key){const p=people[key];
 if(state.scenario!=='operating'&&['ananya','rahul','meera'].includes(key)){
  openDrawer(p.name,'Customer journey','<div class="detail-summary">'+customer(key)+badge(state.planApproved?'Scheduled':'Awaiting plan approval','blue')+'</div><h3>'+ (state.planApproved?'Outreach scheduled':'Ready for audience review')+'</h3><p class="muted small" style="margin-top:8px">No customer contact or purchase is recorded for this journey.</p><div class="detail-section facts-grid">'+fact('Product',p.product)+fact('Last delivered order',p.delivered)+fact('Repeat window',key==='ananya'?'11–14 Oct':key==='rahul'?'12–16 Oct':'12–15 Oct')+fact('Basis',key==='rahul'?'Product-level estimate':'Delivered purchase history')+'</div><section class="detail-section"><h3>Eligibility</h3>'+checks(['Permission recorded for the proposed channel','No newer relevant purchase','No unresolved issue or opt-out','Stock available in the test catalogue'])+'</section>',button('Review plan','plan',true));return;
 }
 let content='<div class="detail-summary">'+customer(key)+badge(key==='support'?'Outreach blocked':key==='optout'?'Suppressed':key==='rahul'?state.checkoutApproved?'Awaiting payment':'Needs approval':key==='meera'&&state.scenario==='operating'?'Order confirmed':'Reminder scheduled',key==='support'?'red':key==='rahul'&&!state.checkoutApproved?'amber':key==='optout'?'':'teal')+'</div>',footer='';
 if(key==='ananya'){
  content+='<h3>Reminder confirmed</h3>'+chat('WhatsApp',[['customer','I still have enough. Remind me on Friday.','10:04'],['agent','Of course. Shall I remind you on Friday, 16 October, at 10 am?','10:04'],['customer','Yes, that works.','10:05'],['agent','I’ll send you a reminder here on 16 October at 10 am.','10:05']])+'<div class="facts-grid">'+fact('Reminder','16 Oct, 10:00 IST','Confirmed by the customer')+fact('Product',p.product,'Same purchased variant')+fact('Next channel','WhatsApp','No overlapping voice contact')+fact('Purchase status','No order recorded')+'</div><section class="detail-section"><h3>What happened</h3><ol class="event-list"><li><strong>Reminder scheduled</strong><span>16 Oct, 10:00 IST · reference sim_reminder_C001</span></li><li><strong>Competing contact cancelled</strong><span>Voice fallback removed from the queue</span></li><li><strong>Eligibility check due before reminder</strong><span>Permissions, new orders, stock and unresolved issues</span></li></ol></section>';
  footer='<span class="muted">Customer-confirmed date</span>'+button('Edit reminder','edit-reminder');
 }else if(key==='rahul'){
  content+='<h3>Same-product checkout requested</h3>'+chat('Voice transcript',[['agent','Would you like to reorder the same 1 litre laundry liquid?','10:16'],['customer','Yes, the same bottle. Just one. Send me the checkout on WhatsApp.','10:16'],['agent','The item price is ₹499. I’ll send you the checkout on WhatsApp so you can review the final total and pay.','10:17']])+'<div class="facts-grid">'+fact('Product & quantity','Laundry liquid · 1 L × 1')+fact('Item price','₹499','Final charges shown at checkout')+fact('Stock','Available','Test catalogue · updated 10:16')+fact('WhatsApp permission','Recorded','Separate from voice permission')+'</div><div class="action-box"><div class="action-title"><span>WhatsApp message</span>'+badge(state.checkoutApproved?'Sent':'Pending approval',state.checkoutApproved?'blue':'amber')+'</div><div class="action-body">Hi Rahul, here’s your checkout for one 1 L bottle of laundry liquid. Please review the total and delivery details before paying.<div style="margin-top:10px">'+textButton('View attached checkout','checkout-preview','external')+'</div></div></div><section class="detail-section"><h3>Checks before sending</h3>'+checks(['Same purchased SKU and quantity confirmed','WhatsApp permission present','No newer relevant order or unresolved issue','Within approved contact and spend limits'])+'</section><details class="disclosure"><summary>View source and action details</summary><p>Commerce, payment and communication records in this workspace are synthetic. '+(state.checkoutApproved?'Send receipt: sim_send_C002. Payment remains unconfirmed.':'Checkout receipt: sim_checkout_C002. No order or payment is confirmed.')+'</p></details>';
  if(state.owner==='merchant'){content+='<div class="pending-approval-note">You control this conversation. Autonomous actions are on hold.</div><div class="field"><label class="input-label" for="manual-reply">Message to Rahul</label><textarea id="manual-reply" rows="3" style="width:100%" placeholder="Write a reply"></textarea></div>';footer='<span class="muted">Merchant takeover</span>'+button('Hand back','handback')+button('Send message','manual-message',true);}
  else footer='<span class="muted">'+(state.paused?'Agent paused':state.planNeedsReview?'Plan needs review':state.checkoutApproved?'Payment not confirmed':'Approval required')+'</span>'+button('Take over','takeover')+(!state.checkoutApproved?button('Approve & send','approve-checkout',true,'',state.paused||state.planNeedsReview||state.disconnected||!state.planApproved?'disabled':''):'');
  if(state.messages.length)content+='<section class="detail-section"><h3>Your messages</h3>'+state.messages.map(message=>'<div class="bubble agent">'+escape(message)+'</div>').join('')+'</section>';
 }else if(key==='meera'){
  content+='<h3>'+(state.scenario==='operating'?'Purchase confirmed':'Awaiting a customer reply')+'</h3><p class="muted small" style="margin-top:8px">'+(state.scenario==='operating'?'Meera placed this order outside the agent checkout link. Further reorder contact was cancelled.':'No payment or order evidence has arrived for this journey.')+'</p><div class="detail-section facts-grid">'+fact('Order',state.scenario==='operating'?'LE-1048':'Not recorded')+fact('Net revenue',state.scenario==='operating'?'₹499':'—')+fact('Payment',state.scenario==='operating'?'Matched to order':'Not confirmed')+fact('Delivery','Not delivered yet')+'</div>'+(state.scenario==='operating'?'<section class="detail-section"><h3>Purchase evidence</h3>'+checks(['Customer and order matched','SKU, amount and currency matched','Payment and commerce order reconciled'])+'</section><section class="detail-section"><h3>Journey updates</h3><ol class="event-list"><li><strong>Brand order confirmed</strong><span>12 Oct, 11:12 IST · sim_order_C003</span></li><li><strong>Reorder contact cancelled</strong><span>No further message or call queued</span></li><li><strong>Order added to outcomes</strong><span>Recorded once, including its outside-link origin</span></li></ol></section>':'');footer=textButton('View outcomes','outcomes');
 }else if(key==='support'){
  content+='<h3>Previous order not received</h3>'+chat('WhatsApp',[['customer','My order hasn’t arrived. Can someone help?','10:22'],['agent','I’ll pass this to the support team. Reorder messages are on hold while they review the delivery.','10:22']])+'<div class="facts-grid">'+fact('Order','LE-1031','Delivery not confirmed')+fact('Case','SUP-006','Delivery issue')+fact('Owner',state.supportOwner?'You':'Not assigned')+fact('Reorder outreach','Blocked','Customer is outside the sales audience')+'</div><section class="detail-section"><h3>Next step</h3><p class="muted small">Review delivery tracking and follow up with the customer. The agent will not promise a delivery date.</p></section>';footer='<span class="muted">Sales outreach remains blocked</span>'+(state.supportOwner?button('View case details','support-case'):button('Assign to me','assign-support',true));
 }else{
  content+='<h3>Marketing contact stopped</h3>'+chat('WhatsApp',[['customer','Stop sending me marketing messages.','09:18']])+'<div class="facts-grid">'+fact('Suppression','Active','Applies immediately')+fact('Queued outreach','Cancelled','WhatsApp and voice')+fact('Recorded','12 Oct, 09:18 IST')+fact('Receipt','sim_suppression_C005')+'</div><div class="detail-section notice warning">'+icon('ban')+'<div>Plan approval cannot override this opt-out.</div></div>';footer='<span class="muted">No further marketing contact permitted</span>';
 }
 openDrawer(p.name,key==='support'?'Support case':key==='optout'?'Contact permission':'Customer journey',content,footer);
}
function environment(){openModal('Test mode','<p>This workspace contains synthetic customers, orders and conversations. Actions are stored locally in your browser. No live account is connected and no customer message, call or payment is made.</p><div class="section-space">'+checks(['Customer-facing layouts and review flows','Simulated commerce and payment evidence','Test data kept separate from live sources'])+'</div>',button('Manage test data','test-data'));}
function testData(){openModal('Test workspace','<p>Choose a scenario to inspect the merchant experience. Changing scenarios replaces this workspace’s test data and settings.</p><div class="mode-options">'+[['operating','Active plan','Reminders, approvals and a confirmed outside-link order.'],['first-plan','First plan','Review an audience before any contact is scheduled.'],['disconnected','Disconnected commerce','Inspect blocked actions and connection recovery.'],['setup','New installation','Configure and install the agent.']].map(([value,title,description])=>'<label class="mode-option"><input type="radio" name="scenario" value="'+value+'" '+(state.scenario===value?'checked':'')+'><div><strong>'+title+'</strong><span>'+description+'</span></div></label>').join('')+'</div>',button('Cancel','close-modal')+button('Load scenario','load-scenario',true));}
function pause(){if(state.paused){openModal('Resume outreach?','<p>Customer permissions, new orders and current plan limits will be checked before the next action.</p>'+(state.disconnected||state.planNeedsReview?'<div class="pending-approval-note">'+(state.disconnected?'Commerce is disconnected. Review the connection first.':'Your plan requires approval under the current policy.')+'</div>':''),button('Keep paused','close-modal')+button('Resume agent','confirm-resume',true,'',state.disconnected||state.planNeedsReview?'disabled':''));}else openModal('Pause outreach?','<p>New messages and calls will stop. Scheduled reminders remain saved. Order updates and customer opt-outs will continue to process.</p>',button('Keep active','close-modal')+button('Pause agent','confirm-pause',true));}
function reviewPolicy(){const form=$('#policy-form');if(!form.reportValidity())return;const values=new FormData(form);const next={start:values.get('start'),end:values.get('end'),cap:Number(values.get('cap')),budget:Number(values.get('budget')),mode:values.get('mode')};if(next.end<=next.start){$('#policy-error').textContent='End time must be later than start time.';$('#contact-end').focus();return;}const changes=[['Contact hours',state.policy.start+'–'+state.policy.end,next.start+'–'+next.end],['Contact cap',state.policy.cap,next.cap],['Spend limit','₹'+state.policy.budget,'₹'+next.budget],['Approval mode',state.mode==='review'?'Review-first':'Within approved limits',next.mode==='review'?'Review-first':'Within approved limits']].filter(x=>String(x[1])!==String(x[2]));if(!changes.length){notify('No changes to save.');return;}window.pendingPolicy=next;openModal('Review policy changes','<p>Saving creates policy version '+(state.policy.version+1)+'. Your active plan will need review before further outreach.</p><div class="diff-list">'+changes.map(([label,before,after])=>'<p><strong>'+label+'</strong><br>'+escape(before)+' → '+escape(after)+'</p>').join('')+'</div>',button('Keep editing','close-modal')+button('Save policy','confirm-policy',true));}
let installStep=0;
function install(){const titles=['Configure','Connections','Review','Activate'];let body='';if(installStep===0)body='<h3>Choose the agent’s mandate</h3><p style="margin-top:8px">Reorder the same purchased product through permitted WhatsApp and voice contact.</p><div class="field"><label class="input-label">Product</label><input value="Laundry liquid · 1 L" readonly aria-label="Selected product"></div><div class="field"><label class="input-label">Approval mode</label><select aria-label="Installation approval mode" id="install-mode"><option value="review" '+(state.mode==='review'?'selected':'')+'>Review-first</option><option value="bounded" '+(state.mode==='bounded'?'selected':'')+'>Within approved limits</option></select></div><p class="field-help">You can change contact hours and budgets in Settings.</p>';
 if(installStep===1)body='<h3>Review source access</h3><p style="margin-top:8px">This workspace uses simulated sources. Live access must be authorised separately.</p>'+providers.map(p=>'<div class="service-row"><div><strong>'+p[0]+'</strong><small>'+p[3]+'</small></div>'+badge('Simulated')+'</div>').join('');
 if(installStep===2)body='<h3>Review installation</h3><p style="margin-top:8px">Installation prepares the agent. Customer contact starts only after a plan is approved.</p><dl class="definition-list"><div><dt>Product</dt><dd>Laundry liquid · 1 L</dd></div><div><dt>Approval mode</dt><dd>'+(state.mode==='review'?'Review-first':'Within approved limits')+'</dd></div><div><dt>Contact hours</dt><dd>10:00–18:00 IST</dd></div><div><dt>Contacts</dt><dd>2 per customer</dd></div><div><dt>Contact spend limit</dt><dd>₹500</dd></div><div><dt>Offers</dt><dd>Off</dd></div><div><dt>Source mode</dt><dd>Simulated</dd></div></dl>';
 if(installStep===3)body='<div class="empty-view" style="padding:24px 0"><div class="empty-icon">'+icon('circlecheck')+'</div><h3>Agent installed</h3><p>Review your first audience before contacting customers.</p></div>';
 openModal('Install Repeat Purchase Agent','<div class="installation-shell"><ol class="install-steps">'+titles.map((title,index)=>'<li class="'+(index===installStep?'current':'')+'" '+(index===installStep?'aria-current="step"':'')+'><span class="step-number">'+(index+1)+'</span>'+title+'</li>').join('')+'</ol><div class="install-body">'+body+'</div></div>',(installStep>0&&installStep<3?button('Back','install-back'):'')+button(installStep===2?'Install agent':installStep===3?'Review audience':'Continue',installStep===3?'finish-install':'install-next',true),true);
}
document.addEventListener('click',eventObject=>{const target=eventObject.target.closest('[data-action]');if(!target)return;eventObject.preventDefault();const action=target.dataset.action;
 if(['dashboard','activity','settings','connections','studio','plan','outcomes'].includes(action)){closeDialogs();go(action);return;}
 if(action.startsWith('journey:')){detail(action.split(':')[1]);return;}
 if(action.startsWith('provider:')){const i=Number(action.split(':')[1]);const p=providers[i];openDrawer(p[0],'Connection access','<div class="detail-summary"><span class="provider-logo '+p[2]+'">'+p[1]+'</span>'+badge(state.disconnected&&i===0?'Disconnected':'Simulated')+'</div><p class="muted small">'+p[3]+'</p><section class="detail-section"><h3>Access used by the agent</h3>'+checks(i===0?['Read permitted customer orders and delivery evidence','Read stock, price and offer eligibility','Prepare same-product checkout']:i===1?['Read verified payment status','Match payments to commerce orders']:i===2?['Read customer replies and delivery state','Send permitted messages within approved limits']:i===3?['Process voice transcripts and confirmed requests','Use separately permitted checkout handoffs']:['Read delivery evidence and unresolved issues','Create support handoffs'])+'</section><details class="disclosure" open><summary>Connection mode</summary><p>This adapter is simulated. No provider credentials or live merchant account are stored.</p></details>',state.disconnected&&i===0?button('Restore test connection','restore-connection',true):'');return;}
 if(action==='test-data'){testData();return;}
 if(action==='load-scenario'){state=initialState($('input[name="scenario"]:checked').value);persist();closeDialogs();go(state.installed?'dashboard':'studio');notify('Test scenario loaded.');return;}
 if(action==='clear-filters'){activityQuery='';activityFilter='all';render();return;}
 if(action==='assign-support'){state.supportOwner='merchant';event('support_assigned','Delivery case SUP-006 assigned to merchant');closeDialogs();render();notify('Delivery issue assigned to you.');return;}
 if(action==='support-case'){openModal('Support case SUP-006','<p><strong>Order LE-1031 · Priya Nair</strong><br>Delivery is not confirmed. You own the follow-up. Reorder outreach remains blocked until the issue is resolved.</p>',button('Done','close-modal',true));return;}
 if(action==='approve-checkout'){if(state.paused||state.disconnected||state.planNeedsReview||!state.planApproved||state.owner==='merchant'||!state.selected.includes('rahul'))return;state.checkoutApproved=true;event('checkout_message','Approved WhatsApp checkout message · sim_send_C002');detail('rahul');render();notify('Checkout message sent in test mode. Payment is pending.');return;}
 if(action==='takeover'){state.owner='merchant';event('takeover','Rahul conversation taken over');detail('rahul');return;}
 if(action==='handback'){if(state.paused||state.disconnected||state.planNeedsReview){notify('Resolve the agent or plan status before handing back.');return;}state.owner='agent';event('handback','Rahul conversation returned to agent');detail('rahul');return;}
 if(action==='manual-message'){const value=$('#manual-reply').value.trim();if(!value){$('#manual-reply').focus();return;}if(state.paused||state.disconnected||state.planNeedsReview){notify('Resolve the agent or plan status before sending.');return;}state.messages.push(value);event('merchant_message','Merchant message saved in test mode');detail('rahul');notify('Message sent in test mode.');return;}
 if(action==='edit-reminder'){openModal('Edit Ananya’s reminder','<p>The customer confirmed 16 Oct at 10:00 IST. A changed date will be held for customer confirmation.</p><div class="field"><label class="input-label" for="reminder-date">Proposed date</label><input id="reminder-date" type="date" min="2026-10-12" value="'+state.reminderDate+'"></div>',button('Keep date','close-modal')+button('Request confirmation','reminder-proposal',true));return;}
 if(action==='reminder-proposal'){const input=$('#reminder-date');if(!input.reportValidity()||!input.value)return;event('reminder_proposal','Proposed '+input.value+'; existing confirmed reminder retained');closeDialogs();notify('Date change queued for confirmation. Existing reminder kept.');return;}
 if(action==='exclusions'){openDrawer('Excluded customers','Eligibility','<div class="service-row"><div><strong>Customer C004</strong><small>Previous order is not delivered.</small></div>'+badge('Excluded')+'</div><div class="service-row"><div><strong>Customer C005</strong><small>Opted out of marketing contact.</small></div>'+badge('Suppressed')+'</div>'+(state.planNeedsReview?'<div class="service-row"><div><strong>Meera Shah · C003</strong><small>New relevant purchase received.</small></div>'+badge('Recent purchase')+'</div>':'')+'<div class="detail-section"><p class="muted small">These customers cannot be added to outreach while the exclusion applies.</p></div>');return;}
 if(action==='approve-plan'){if(state.paused||state.disconnected)return;const date=$('#plan-date');if(!date.reportValidity()||!date.value)return;const keys=state.planNeedsReview?['ananya','rahul']:['ananya','rahul','meera'];const selected=keys.filter(k=>!state.audienceExcluded.includes(k));if(!selected.length){$('#plan-error').textContent='Select at least one eligible customer.';return;}state.planDate=date.value;state.selected=selected;state.assigned=[...new Set([...state.assigned,...selected])];state.planApproved=true;state.planNeedsReview=false;state.installed=true;state.planVersion++;event('plan_approved','Plan RP-014 v'+state.planVersion+' approved for '+selected.length+' customers');render();notify('Plan approved. Outgoing actions follow your approval mode.');return;}
 if(action==='reject-plan'){openModal('Reject this plan?','<p>No new customer contact will be authorised by this plan.</p>',button('Keep reviewing','close-modal')+button('Reject plan','confirm-reject',true));return;}
 if(action==='confirm-reject'){state.planApproved=false;state.selected=[];event('plan_rejected','Reorder plan rejected');closeDialogs();go('dashboard');notify('Plan rejected.');return;}
 if(action==='save-policy'){reviewPolicy();return;}
 if(action==='confirm-policy'){const next=window.pendingPolicy;if(!next)return;state.policy={...state.policy,start:next.start,end:next.end,cap:next.cap,budget:next.budget,version:state.policy.version+1};state.mode=next.mode;state.planNeedsReview=state.planApproved;event('policy_saved','Policy v'+state.policy.version+' saved; affected plan held');delete window.pendingPolicy;closeDialogs();render();notify('Policy saved. Review the affected plan before outreach.');return;}
 if(action==='checkout-preview'){openModal('Checkout details','<p><strong>Laundry liquid · 1 L × 1</strong></p><dl class="definition-list"><div><dt>Item price</dt><dd>₹499</dd></div><div><dt>Discount</dt><dd>None</dd></div><div><dt>Checkout reference</dt><dd>sim_checkout_C002</dd></div></dl><p class="field-help" style="margin-top:16px">Test checkout. No live payment link is created. Delivery and tax details must be verified by the connected commerce checkout.</p>',button('Close','close-modal',true));return;}
 if(action==='calculation'){if(!state.orderConfirmed){openDrawer('Contribution inputs','Cost completeness','<p class="muted small">No confirmed order is recorded. Product, delivery, payment, communication and agent costs must be verified before contribution can be calculated.</p>');return;}openDrawer('Order calculation','Order LE-1048','<dl class="definition-list"><div><dt>Item net sales</dt><dd>₹499</dd></div><div><dt>Discount</dt><dd>₹0</dd></div><div><dt>Refunds recorded</dt><dd>₹0</dd></div><div><dt>Net revenue</dt><dd>₹499</dd></div><div><dt>Product cost</dt><dd>Missing</dd></div><div><dt>Delivery cost</dt><dd>Missing</dd></div><div><dt>Payment, communication & agent costs</dt><dd>Not verified</dd></div><div><dt>Net contribution</dt><dd>Not available</dd></div></dl><section class="detail-section"><p class="muted small">Taxes are excluded from this test fixture. Returns have not matured. Incremental impact has not been measured.</p></section>');return;}
 if(action==='confirm-pause'){state.paused=true;event('agent_paused','New outreach paused');closeDialogs();render();notify('Agent paused. Scheduled reminders are saved.');return;}
 if(action==='confirm-resume'){if(state.disconnected||state.planNeedsReview)return;state.paused=false;event('agent_resumed','Resume checks passed in test mode');closeDialogs();render();notify('Agent resumed in test mode.');return;}
 if(action==='restore-connection'){state.disconnected=false;event('connection_restored','Simulated commerce data restored');closeDialogs();render();notify('Test commerce connection restored.');return;}
 if(action==='install'){installStep=0;install();return;}
 if(action==='install-back'){installStep=Math.max(0,installStep-1);install();return;}
 if(action==='install-next'){if(installStep===0)state.mode=$('#install-mode').value;installStep++;if(installStep===3){state.installed=true;event('installed','Agent installed; no audience approved');}install();render();return;}
 if(action==='finish-install'){closeDialogs();go('plan');return;}
 if(action==='close-modal'){closeDialogs();return;}
});
document.addEventListener('change',eventObject=>{if(eventObject.target.id==='activity-filter'){activityFilter=eventObject.target.value;render();}if(eventObject.target.dataset.person){const key=eventObject.target.dataset.person;state.audienceExcluded=eventObject.target.checked?state.audienceExcluded.filter(x=>x!==key):[...new Set([...state.audienceExcluded,key])];persist();const count=document.querySelectorAll('[data-person]:checked').length;const approve=$('[data-action="approve-plan"]');if(approve){approve.textContent='Approve '+count+' '+(count===1?'customer':'customers');approve.disabled=state.paused||state.disconnected||count===0;}}});
document.addEventListener('input',eventObject=>{if(eventObject.target.id==='activity-search'){const input=eventObject.target,position=input.selectionStart;activityQuery=input.value;render();$('#activity-search').focus();$('#activity-search').setSelectionRange(position,position);}});
document.addEventListener('submit',eventObject=>{if(eventObject.target.id==='policy-form'){eventObject.preventDefault();reviewPolicy();}});
$('#environment-button').addEventListener('click',environment);$('#test-data-button')?.addEventListener('click',testData);$('#pause-button').addEventListener('click',pause);$('#resume-inline').addEventListener('click',pause);
$('#menu-toggle').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));});
$('#support-button').addEventListener('click',()=>openModal('Help & support','<p>Need help with approvals, customer activity or connection access? Review the agent’s policy and the source details shown with each action.</p><div class="service-row"><div><strong>Customer issue</strong><small>Review an assigned delivery case.</small></div>'+textButton('Open case','journey:support')+'</div><div class="service-row"><div><strong>Connection issue</strong><small>Inspect permissions and data availability.</small></div>'+textButton('Connections','connections')+'</div>'));
$('#drawer-close').innerHTML=icon('close');$('#modal-close').innerHTML=icon('close');$('#menu-toggle').innerHTML=icon('menu');$('#drawer-close').addEventListener('click',()=>$('#drawer').close());$('#modal-close').addEventListener('click',()=>$('#modal').close());
['drawer','modal'].forEach(id=>$('#'+id).addEventListener('close',()=>{if(lastFocus?.isConnected)lastFocus.focus();else $('#workspace').focus();}));
window.addEventListener('hashchange',()=>{closeDialogs();$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');render();});
render();
})();
